from pathlib import Path

def write(path: str, content: str) -> None:
    target = Path(path)
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(content, encoding='utf-8')

write('app/api/routes/datasets.py', 'from __future__ import annotations\n\nfrom fastapi import APIRouter, Depends, File, Form, HTTPException, UploadFile, status\nfrom sqlalchemy.orm import Session\n\nfrom app.api.deps import ApiPrincipal, get_db, require_admin_key, require_api_key\nfrom app.db.models import DatasetManifest\nfrom app.schemas.dataset import DatasetRead, OpenMeteoDatasetRequest\nfrom app.services.audit_service import record_audit\nfrom app.services.dataset_service import build_open_meteo_dataset, save_uploaded_dataset\n\nrouter = APIRouter(prefix="/datasets", tags=["datasets"])\n\n\ndef _read(item: DatasetManifest) -> DatasetRead:\n    return DatasetRead(\n        id=item.id,\n        name=item.name,\n        source_type=item.source_type,\n        station_code=item.station_code,\n        file_uri=item.file_uri,\n        checksum_sha256=item.checksum_sha256,\n        row_count=item.row_count,\n        schema_version=item.schema_version,\n        date_start=item.date_start,\n        date_end=item.date_end,\n        quality_report=item.quality_report,\n        created_at=item.created_at,\n    )\n\n\n@router.get("", response_model=list[DatasetRead])\ndef list_datasets(\n    db: Session = Depends(get_db),\n    _: ApiPrincipal = Depends(require_api_key),\n) -> list[DatasetRead]:\n    items = db.query(DatasetManifest).order_by(DatasetManifest.created_at.desc()).all()\n    return [_read(item) for item in items]\n\n\n@router.get("/{dataset_id}", response_model=DatasetRead)\ndef get_dataset(\n    dataset_id: str,\n    db: Session = Depends(get_db),\n    _: ApiPrincipal = Depends(require_api_key),\n) -> DatasetRead:\n    item = db.get(DatasetManifest, dataset_id)\n    if item is None:\n        raise HTTPException(status_code=404, detail={"code": "DATASET_NOT_FOUND", "message": dataset_id})\n    return _read(item)\n\n\n@router.post("/upload", response_model=DatasetRead, status_code=status.HTTP_201_CREATED)\ndef upload_dataset(\n    name: str = Form(...),\n    station_code: str | None = Form(None),\n    file: UploadFile = File(...),\n    db: Session = Depends(get_db),\n    principal: ApiPrincipal = Depends(require_admin_key),\n) -> DatasetRead:\n    try:\n        manifest = save_uploaded_dataset(\n            db,\n            name=name,\n            filename=file.filename or "dataset.csv",\n            file_object=file.file,\n            station_code=station_code,\n        )\n    except ValueError as exc:\n        raise HTTPException(status_code=422, detail={"code": "INVALID_DATASET", "message": str(exc)}) from exc\n    record_audit(\n        db,\n        actor_fingerprint=principal.key_fingerprint,\n        action="dataset.uploaded",\n        entity_type="dataset",\n        entity_id=manifest.id,\n        details={"row_count": manifest.row_count},\n    )\n    return _read(manifest)\n\n\n@router.post("/open-meteo", response_model=DatasetRead, status_code=status.HTTP_201_CREATED)\ndef create_open_meteo_dataset(\n    payload: OpenMeteoDatasetRequest,\n    db: Session = Depends(get_db),\n    principal: ApiPrincipal = Depends(require_admin_key),\n) -> DatasetRead:\n    try:\n        manifest = build_open_meteo_dataset(db, **payload.model_dump())\n    except Exception as exc:\n        raise HTTPException(status_code=502, detail={"code": "DATA_INGESTION_FAILED", "message": str(exc)}) from exc\n    record_audit(\n        db,\n        actor_fingerprint=principal.key_fingerprint,\n        action="dataset.open_meteo_created",\n        entity_type="dataset",\n        entity_id=manifest.id,\n        details={"row_count": manifest.row_count, "station_code": payload.station_code},\n    )\n    return _read(manifest)\n')
write('app/api/routes/health.py', 'from __future__ import annotations\n\nfrom datetime import UTC, datetime\n\nfrom fastapi import APIRouter, Depends\nfrom sqlalchemy import text\nfrom sqlalchemy.orm import Session\n\nfrom app.core.config import get_settings\nfrom app.db.session import get_db\nfrom app.schemas.common import HealthResponse\n\nrouter = APIRouter(tags=["health"])\n\n\n@router.get("/health", response_model=HealthResponse)\ndef health() -> HealthResponse:\n    settings = get_settings()\n    return HealthResponse(\n        status="online",\n        service=settings.app_name,\n        environment=settings.app_env,\n        timestamp=datetime.now(UTC),\n        version="1.0.0",\n    )\n\n\n@router.get("/ready")\ndef ready(db: Session = Depends(get_db)) -> dict:\n    db.execute(text("SELECT 1"))\n    return {"status": "ready", "timestamp": datetime.now(UTC)}\n')
write('app/api/routes/models.py', 'from __future__ import annotations\n\nfrom fastapi import APIRouter, Depends, HTTPException\nfrom sqlalchemy.orm import Session\n\nfrom app.api.deps import ApiPrincipal, get_db, require_admin_key, require_api_key\nfrom app.db.models import ModelVersion\nfrom app.schemas.model import (\n    ModelHealthResponse,\n    ModelPromotionRequest,\n    ModelRollbackRequest,\n    ModelVersionRead,\n)\nfrom app.services.audit_service import record_audit\nfrom app.services.model_service import load_model_bundle, model_health, promote_model\n\nrouter = APIRouter(prefix="/models", tags=["models"])\n\n\ndef _read(item: ModelVersion) -> ModelVersionRead:\n    return ModelVersionRead(\n        id=item.id,\n        model_name=item.model_name,\n        version=item.version,\n        status=item.status,\n        artifact_uri=item.artifact_uri,\n        artifact_sha256=item.artifact_sha256,\n        feature_schema_version=item.feature_schema_version,\n        training_dataset_id=item.training_dataset_id,\n        training_start_date=item.training_start_date,\n        training_end_date=item.training_end_date,\n        metrics=item.metrics,\n        hyperparameters=item.hyperparameters,\n        metadata=item.metadata_json,\n        promoted_at=item.promoted_at,\n        retired_at=item.retired_at,\n        created_at=item.created_at,\n    )\n\n\n@router.get("/health", response_model=ModelHealthResponse)\ndef get_model_health(\n    db: Session = Depends(get_db),\n    _: ApiPrincipal = Depends(require_api_key),\n) -> ModelHealthResponse:\n    return ModelHealthResponse.model_validate(model_health(db))\n\n\n@router.get("", response_model=list[ModelVersionRead])\ndef list_models(\n    db: Session = Depends(get_db),\n    _: ApiPrincipal = Depends(require_api_key),\n) -> list[ModelVersionRead]:\n    return [_read(item) for item in db.query(ModelVersion).order_by(ModelVersion.created_at.desc()).all()]\n\n\n@router.get("/{version}", response_model=ModelVersionRead)\ndef get_model(\n    version: str,\n    db: Session = Depends(get_db),\n    _: ApiPrincipal = Depends(require_api_key),\n) -> ModelVersionRead:\n    item = db.query(ModelVersion).filter(ModelVersion.version == version).one_or_none()\n    if item is None:\n        raise HTTPException(status_code=404, detail={"code": "MODEL_NOT_FOUND", "message": version})\n    return _read(item)\n\n\n@router.post("/promote", response_model=ModelVersionRead)\ndef promote(\n    payload: ModelPromotionRequest,\n    db: Session = Depends(get_db),\n    principal: ApiPrincipal = Depends(require_admin_key),\n) -> ModelVersionRead:\n    item = db.query(ModelVersion).filter(ModelVersion.version == payload.model_version).one_or_none()\n    if item is None:\n        raise HTTPException(status_code=404, detail={"code": "MODEL_NOT_FOUND", "message": payload.model_version})\n    try:\n        load_model_bundle(item)\n    except Exception as exc:\n        raise HTTPException(status_code=422, detail={"code": "MODEL_ARTIFACT_INVALID", "message": str(exc)}) from exc\n    item = promote_model(db, item)\n    record_audit(\n        db,\n        actor_fingerprint=principal.key_fingerprint,\n        action="model.promoted",\n        entity_type="model_version",\n        entity_id=item.id,\n        details={"version": item.version, "reason": payload.reason},\n    )\n    return _read(item)\n\n\n@router.post("/rollback", response_model=ModelVersionRead)\ndef rollback(\n    payload: ModelRollbackRequest,\n    db: Session = Depends(get_db),\n    principal: ApiPrincipal = Depends(require_admin_key),\n) -> ModelVersionRead:\n    item = db.query(ModelVersion).filter(ModelVersion.version == payload.model_version).one_or_none()\n    if item is None:\n        raise HTTPException(status_code=404, detail={"code": "MODEL_NOT_FOUND", "message": payload.model_version})\n    item = promote_model(db, item)\n    record_audit(\n        db,\n        actor_fingerprint=principal.key_fingerprint,\n        action="model.rolled_back",\n        entity_type="model_version",\n        entity_id=item.id,\n        details={"version": item.version, "reason": payload.reason},\n    )\n    return _read(item)\n')
write('app/api/routes/outcomes.py', 'from __future__ import annotations\n\nfrom fastapi import APIRouter, Depends\nfrom sqlalchemy.orm import Session\n\nfrom app.api.deps import ApiPrincipal, get_db, require_admin_key\nfrom app.schemas.outcome import OutcomeCreate, OutcomeRead\nfrom app.services.audit_service import record_audit\nfrom app.services.outcome_service import record_outcome\n\nrouter = APIRouter(prefix="/outcomes", tags=["outcomes"])\n\n\n@router.post("", response_model=OutcomeRead)\ndef create_outcome(\n    payload: OutcomeCreate,\n    db: Session = Depends(get_db),\n    principal: ApiPrincipal = Depends(require_admin_key),\n) -> OutcomeRead:\n    outcome, evaluations = record_outcome(db, payload)\n    record_audit(\n        db,\n        actor_fingerprint=principal.key_fingerprint,\n        action="outcome.recorded",\n        entity_type="outcome",\n        entity_id=outcome.id,\n        details={"market_id": payload.market_id, "evaluations_created": evaluations},\n    )\n    return OutcomeRead(\n        id=outcome.id,\n        market_id=outcome.market_id,\n        station_code=outcome.station_code,\n        official_value=outcome.official_value,\n        official_source=outcome.official_source,\n        settled_at=outcome.settled_at,\n        metadata=outcome.metadata_json,\n        created_at=outcome.created_at,\n        evaluations_created=evaluations,\n    )\n')
